/**
 * Normalizes source text without changing its words.
 * @param {unknown} value - Original mail field.
 * @returns {string} Normalized text or an empty string.
 */
function normalizeSource(value) {
  return typeof value === 'string' ? value.normalize('NFKC').replace(/\s+/g, ' ').trim() : '';
}


/**
 * Rejects identifier-only or greeting-only evidence.
 * @param {string} value - Quoted evidence from the mail.
 * @returns {boolean} Whether at least two non-filler words remain.
 */
function hasRequestWords(value) {
  const text = normalizeSource(value).replace(/\S*\d\S*/g, '');
  const words = text.toLowerCase().match(/\p{L}+/gu) || [];
  const filler = new Set(['test', 'hallo', 'hello', 'hi', 'danke', 'thanks', 'gruß', 'grüße', 'regards']);
  return words.filter(word => word.length > 1 && !filler.has(word)).length >= 2;
}


/**
 * Requires an actionable request supported by the original mail.
 * @param {Object} data - Ticket and original email fields.
 * @param {string[]} errors - Collected validation errors.
 */
function checkEvidence(data, errors) {
  const ticket = data.ticket || {};
  const sources = [data.emailSubject, data.emailBody].map(normalizeSource);
  const quote = normalizeSource(ticket.sourceQuote);
  const supported = quote && sources.some(source => source.includes(quote));
  if (ticket.hasActionableRequest !== true || !supported || !hasRequestWords(quote)) {
    errors.push('Kein belegbares fachliches Anliegen in der E-Mail. Manuelle Prüfung erforderlich.');
  }
}


/** Prüft, ob ein nicht leerer Text vorhanden ist. */
function hasText(value) {
  return typeof value === 'string' && value.trim().length > 0;
}


/** Akzeptiert null oder ein tatsächlich gültiges Kalenderdatum. */
function isValidDeadline(value) {
  if (value === null) return true;
  if (typeof value !== 'string') return false;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  if (value.startsWith('0000')) return false;
  const date = new Date(value + 'T00:00:00.000Z');
  return !Number.isNaN(date.getTime()) &&
    date.toISOString().slice(0, 10) === value;
}


/** Prüft die von der KI erzeugten Ticketfelder. */
function checkTicket(ticket, errors) {
  if (!hasText(ticket.description)) errors.push('Beschreibung fehlt.');
  const categories = new Map([['bug', 'technical-task'], ['technical-task', 'technical-task'], ['feature', 'user-story']]);
  if (!categories.has(ticket.issueType) || categories.get(ticket.issueType) !== ticket.category) {
    errors.push('Ticketart und Board-Kategorie passen nicht zusammen.');
  }
  if (!hasText(ticket.title)) errors.push('Titel fehlt.');
  if (!['urgent', 'medium', 'low'].includes(ticket.priority)) {
    errors.push('Priorität ist ungültig.');
  }
  if (!isValidDeadline(ticket.deadline)) {
    errors.push('Die angegebene Deadline ist kein gültiges Kalenderdatum.');
  }
}


/** Prüft Pflichtangaben zur ursprünglichen E-Mail. */
function checkEmail(data, errors) {
  if (!hasText(data.emailBody)) errors.push('Der Nachrichtentext der E-Mail fehlt.');
  const fields = ['gmailMessageId', 'mailMessageId', 'deduplicationKey'];
  for (const field of fields) {
    if (!hasText(data[field])) errors.push(field + ' fehlt.');
  }
  for (const field of ['senderName', 'emailSubject']) {
    if (data[field] != null && typeof data[field] !== 'string') {
      errors.push(field + ' muss Text sein.');
    }
  }
  if (typeof data.senderEmail !== 'string' ||
      !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.senderEmail)) {
    errors.push('Absenderadresse fehlt oder hat ein ungültiges Format.');
  }
}


/** Ergänzt das Prüfergebnis und erhält die Zuordnung zur Eingabe. */
function validateItem(item, index) {
  const data = item.json;
  const errors = [];
  checkTicket(data.ticket ?? {}, errors);
  checkEmail(data, errors);
  checkEvidence(data, errors);
  return {
    json: {
      ...data,
      validation: { valid: errors.length === 0, errors }
    },
    pairedItem: { item: index }
  };
}

return $input.all().map(validateItem);

