return $input.all().map((item, index) => {
  const writes = $('Ticketabschluss vorbereiten').itemMatching(index).json.commit.writes;
  const [, counter, reservation] = writes;
  const error = item.json.error;
  const message = typeof error === 'string' ? error : error?.message;
  const fields = {
    status: { stringValue: 'failed' },
    quotaState: { stringValue: 'released' },
    failedAt: { timestampValue: $now.toUTC().toISO() },
    errorMessage: { stringValue: message || 'Ticket konnte nicht gespeichert werden.' }
  };
  // Die Mailversion bindet beide Änderungen an genau diese Reservierung.
  const commit = { writes: [
    { update: { name: reservation.update.name, fields },
      updateMask: { fieldPaths: Object.keys(fields) },
      currentDocument: reservation.currentDocument },
    { transform: { document: counter.update.name, fieldTransforms: [
      { fieldPath: 'reservedCount', increment: { integerValue: '-1' } }
    ] }, currentDocument: { exists: true } }
  ] };
  return { json: { commit }, pairedItem: { item: index } };
});

